import java.io.*;
import java.util.*;

public class Main {
    static final int INF = 1_000_000_000;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            while (ptr < len && buffer[ptr] <= ' ') ptr++;
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                while (ptr < len && buffer[ptr] <= ' ') ptr++;
            }
            int value = 0;
            while (ptr < len && buffer[ptr] > ' ') {
                value = value * 10 + buffer[ptr++] - '0';
            }
            return value;
        }
    }

    static int[] parent, depth, head, position;
    static int[][] up;
    static int[] seg;
    static int segBase;

    static void update(int index, int value) {
        int i = segBase + index;
        seg[i] = value;
        for (i >>= 1; i > 0; i >>= 1) {
            seg[i] = Math.min(seg[i << 1], seg[i << 1 | 1]);
        }
    }

    static int rangeMin(int left, int right) {
        int result = INF;
        int l = segBase + left;
        int r = segBase + right;
        while (l <= r) {
            if ((l & 1) == 1) result = Math.min(result, seg[l++]);
            if ((r & 1) == 0) result = Math.min(result, seg[r--]);
            l >>= 1;
            r >>= 1;
        }
        return result;
    }

    static int shallowestMarkedAncestor(int v) {
        if (v == 1) return 0;
        int x = parent[v];
        int bestDepth = INF;
        int result = 0;

        while (head[x] != head[1]) {
            int h = head[x];
            int d = rangeMin(position[h], position[x]);
            if (d < bestDepth) {
                bestDepth = d;
                // Recover the marked node at this depth from its position.
                // Positions along each heavy chain increase with depth.
                int lo = position[h], hi = position[x];
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (rangeMin(position[h], mid) <= d) hi = mid;
                    else lo = mid + 1;
                }
                result = nodeAtPosition[lo];
            }
            x = parent[h];
        }

        int d = rangeMin(position[1], position[x]);
        if (d < bestDepth) {
            int lo = position[1], hi = position[x];
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (rangeMin(position[1], mid) <= d) hi = mid;
                else lo = mid + 1;
            }
            result = nodeAtPosition[lo];
        }
        return result;
    }

    static int[] nodeAtPosition;

    static int ancestor(int v, int steps) {
        int bit = 0;
        while (steps > 0) {
            if ((steps & 1) != 0) v = up[bit][v];
            steps >>>= 1;
            bit++;
        }
        return v;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        parent = new int[n + 1];
        int[] firstChild = new int[n + 1];
        int[] to = new int[n - 1];
        int[] next = new int[n - 1];
        Arrays.fill(firstChild, -1);

        int edge = 0;
        for (int v = 2; v <= n; v++) {
            parent[v] = fs.nextInt();
            to[edge] = v;
            next[edge] = firstChild[parent[v]];
            firstChild[parent[v]] = edge++;
        }

        int log = 1;
        while ((1 << log) <= n) log++;
        up = new int[log][n + 1];
        depth = new int[n + 1];
        for (int v = 2; v <= n; v++) {
            depth[v] = depth[parent[v]] + 1;
            up[0][v] = parent[v];
        }
        for (int j = 1; j < log; j++) {
            for (int v = 1; v <= n; v++) {
                up[j][v] = up[j - 1][up[j - 1][v]];
            }
        }

        int[] subtreeSize = new int[n + 1];
        int[] heavy = new int[n + 1];
        Arrays.fill(subtreeSize, 1);
        for (int v = n; v >= 2; v--) {
            int p = parent[v];
            subtreeSize[p] += subtreeSize[v];
            if (heavy[p] == 0 || subtreeSize[v] > subtreeSize[heavy[p]]) {
                heavy[p] = v;
            }
        }

        head = new int[n + 1];
        position = new int[n + 1];
        nodeAtPosition = new int[n];
        int[] stack = new int[n];
        int stackSize = 0;
        stack[stackSize++] = 1;
        int timer = 0;

        while (stackSize > 0) {
            int start = stack[--stackSize];
            for (int v = start; v != 0; v = heavy[v]) {
                head[v] = start;
                position[v] = timer;
                nodeAtPosition[timer++] = v;
                for (int e = firstChild[v]; e != -1; e = next[e]) {
                    int child = to[e];
                    if (child != heavy[v]) stack[stackSize++] = child;
                }
            }
        }

        segBase = 1;
        while (segBase < n) segBase <<= 1;
        seg = new int[segBase << 1];
        Arrays.fill(seg, INF);

        int q = fs.nextInt();
        StringBuilder out = new StringBuilder();

        while (q-- > 0) {
            int type = fs.nextInt();
            int v = fs.nextInt();

            if (type == 2) {
                update(position[v], depth[v]);
            } else {
                int k = fs.nextInt();
                int marked = shallowestMarkedAncestor(v);
                if (marked != 0) {
                    out.append(ancestor(marked, k - 1)).append('\n');
                } else {
                    out.append(ancestor(v, k)).append('\n');
                }
            }
        }

        System.out.print(out);
    }
}
